export function AssetDistributionChartCard({
  title,
  description,
  distribution,
  totalCount,
  countUnit,
  loading,
  error,
  cardClassName,
  chartContainerClassName,
  emptyMessage,
  showCountBadge = true,
}: {
  title: string;
  description: string;
  distribution: AssetScoreDistribution | null;
  totalCount: number;
  countUnit: string;
  loading: boolean;
  error: string | null;
  cardClassName?: string;
  chartContainerClassName?: string;
  emptyMessage?: string;
  showCountBadge?: boolean;
}) {
  const chartData = toAssetDistributionChartRows(distribution);
  const hasData = chartData.some((row) => row.count > 0);

  return (
    <Card
      className={cn(
        "overflow-hidden border-slate-200 bg-white",
        cardClassName ?? ""
      )}
    >
      <CardHeader className="gap-2 border-b border-slate-200/80 bg-white">
        <div className="flex items-start justify-between gap-3">
          <div>
            <CardTitle className="text-base text-slate-900">{title}</CardTitle>
            <p className="mt-1 text-sm text-slate-500">{description}</p>
          </div>
          {showCountBadge ? (
            <div className="rounded-full border border-slate-200 bg-slate-50 px-3 py-1 text-xs font-semibold text-slate-700">
              {totalCount.toLocaleString()} {countUnit}
            </div>
          ) : null}
        </div>
      </CardHeader>
      <CardContent className="flex flex-1 flex-col pt-5">
        {loading ? (
          <ChartPlaceholder>Loading distribution…</ChartPlaceholder>
        ) : error ? (
          <ChartPlaceholder tone="error">{error}</ChartPlaceholder>
        ) : !hasData ? (
          <ChartPlaceholder>{emptyMessage ?? "No assets match the current filters."}</ChartPlaceholder>
        ) : (
          <>
            <ChartContainer
              config={chartConfig}
              className={cn(
                "h-[250px] w-full",
                chartContainerClassName ?? ""
              )}
            >
              <BarChart
                accessibilityLayer
                data={chartData}
                layout="vertical"
                margin={{ left: 20, right: 32, top: 4, bottom: 4 }}
              >
                <CartesianGrid horizontal={false} strokeDasharray="3 3" />
                <YAxis
                  dataKey="label"
                  type="category"
                  tickLine={false}
                  tickMargin={10}
                  axisLine={false}
                  width={72}
                />
                <XAxis dataKey="count" type="number" hide />
                <ChartTooltip
                  cursor={{ fill: "rgba(0, 175, 102, 0.08)" }}
                  content={<ChartTooltipContent indicator="line" hideLabel />}
                />
                <Bar dataKey="count" fill="var(--color-count)" radius={4}>
                  <LabelList
                    dataKey="count"
                    position="right"
                    offset={10}
                    className="fill-slate-700"
                    fontSize={12}
                    fontWeight={700}
                  />
                </Bar>
              </BarChart>
            </ChartContainer>
            <ul className="sr-only">
              {chartData.map((row) => (
                <li key={row.key}>{`${row.label} ${row.count}`}</li>
              ))}
            </ul>
          </>
        )}
      </CardContent>
    </Card>
  );
}

