export function AssetInventoryPanel({
  businessUnit,
  businessService,
  application,
  directOnly = false,
  wrapInventoryContentInCard = false,
  tableVariant = "default",
  refreshToken,
  onOpenAsset,
}: {
  businessUnit?: string | null;
  businessService?: string | null;
  application?: string | null;
  directOnly?: boolean;
  wrapInventoryContentInCard?: boolean;
  tableVariant?: "default" | "businessServiceDirect";
  refreshToken: number;
  onOpenAsset: (asset: AssetSummary) => void;
}) {
  const {
    searchDraft,
    setSearchDraft,
    applySearch,
    status,
    setStatus,
    environment,
    setEnvironment,
    compliance,
    setCompliance,
    sortBy,
    setSortBy,
    sortOrder,
    toggleSortOrder,
    data,
    assets,
    loading,
    error,
    analytics,
    analyticsLoading,
    analyticsError,
    page,
    pageSize,
    totalPages,
    pageNumbers,
    goToPage,
    statusOptions,
    environmentOptions,
    complianceOptions,
  } = useAssetInventoryState({
    businessUnit,
    businessService,
    application,
