    refreshToken,
  });
  const isBusinessServiceDirectTable = tableVariant === "businessServiceDirect";

  return (
    <div className="space-y-4">
      <AssetDistributionCharts
        analytics={analytics}
        loading={analyticsLoading}
        error={analyticsError}
