export function formatCurrency(value?: number | null) {
  if (value === null || value === undefined || Number.isNaN(value)) return "-";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(value);
}

export function formatPercent(value?: number | null, digits = 0) {
  if (value === null || value === undefined || Number.isNaN(value)) return "-";
  return `${(value * 100).toFixed(digits)}%`;
}

export function getRiskDrivers(
  finding: ScoredFinding,
  prediction: FairLossPredictionResponse
) {
  const raw = [
    {
      label: "Weak controls",
      value: Math.max(0.08, 1 - prediction.control_score),
    },
    {
      label: "Exploit likelihood",
      value: Math.max(0.08, finding.epss_score ?? prediction.vulnerability),
    },
    {
      label: "Primary loss",
      value: Math.max(0.08, prediction.primary_mean / Math.max(prediction.primary_mean + prediction.secondary_mean, 1)),
    },
    {
      label: "Secondary loss",
      value: Math.max(0.08, prediction.secondary_mean / Math.max(prediction.primary_mean + prediction.secondary_mean, 1)),
    },
    {
      label: "Known exploitation",
      value: finding.isKev ? 0.8 : 0.12,
    },
  ];
  const total = raw.reduce((sum, item) => sum + item.value, 0);
  return raw.map((item) => ({
    ...item,
    percent: item.value / total,
  }));
}

import type { ScoredFinding } from "../../types";

export function getNormalizedFindingTitle(
  finding: ScoredFinding,
  fallbackPrefix = "Finding"
) {
  const raw = (finding.display_name || "").trim();
  const cve = (finding.cve_id || "").trim().toUpperCase();

  if (!raw) {
    return cve || `${fallbackPrefix} ${finding.id}`.trim();
  }
  if (!cve) {
    return raw;
  }

  const suffixPattern = new RegExp(`:\\s*${cve}$`, "i");
  const exactPattern = new RegExp(`^${cve}$`, "i");

  if (suffixPattern.test(raw)) {
    const stripped = raw.replace(suffixPattern, "").trim();
    if (stripped) return stripped;
  }
  if (exactPattern.test(raw)) {
    return cve;
  }

  return raw;
}

export function riskBandWeight(value?: string | null) {
  switch ((value ?? "").toLowerCase()) {
    case "critical":
      return 4;
    case "high":
      return 3;
    case "medium":
      return 2;
    case "low":
      return 1;
    default:
      return 0;
  }
}

export function riskBandPillClass(band?: string | null) {
  const value = (band || "").toLowerCase();
  if (value === "critical") return "bg-rose-100 text-rose-700";
  if (value === "high") return "bg-orange-100 text-orange-700";
  if (value === "medium") return "bg-amber-100 text-amber-700";
  if (value === "low") return "bg-emerald-100 text-emerald-700";
  return "bg-slate-100 text-slate-700";
}

import type { ScoredFinding } from "../../types";

export type NormalizedFindingStatus = "Active" | "Inactive" | "Fixed";

export function normalizeFindingStatus(finding: ScoredFinding): NormalizedFindingStatus {
  const combined = [finding.status, finding.lifecycle_status]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();

  if (/fixed|closed|resolved|remediated/.test(combined)) {
    return "Fixed";
  }
  if (/inactive|unactive|retired/.test(combined)) {
    return "Inactive";
  }
  if (/active|open|new/.test(combined)) {
    return "Active";
  }
  return "Active";
}

export function findingStatusTone(
  status: NormalizedFindingStatus
): "low" | "neutral" | "dark" {
  if (status === "Fixed") return "dark";
  if (status === "Active") return "low";
  return "neutral";
}

export function formatDate(value?: string | null, withTime = false) {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return value;
  return withTime ? date.toLocaleString() : date.toLocaleDateString();
}

export function formatAgeDays(value?: number | null, fallback = "-") {
  if (value === null || value === undefined || Number.isNaN(value)) {
    return fallback;
  }
  return `${value.toFixed(0)}d`;
}

export function formatNumber(
  value?: number | null,
  digits = 1,
  fallback = "-"
) {
  if (value === null || value === undefined || Number.isNaN(value)) {
    return fallback;
  }
  return value.toFixed(digits);
}

export function formatNullableNumber(
  value?: number | null,
  digits = 1,
  fallback = "-"
) {
  return formatNumber(value, digits, fallback);
}

export function isPopulatedText(value?: string | null) {
  return Boolean(value && value.trim());
}

export function joinDisplayText(
  values: Array<string | null | undefined>,
  fallback = "-"
) {
  return values.filter((value) => isPopulatedText(value ?? null)).join(" / ") || fallback;
}

export function formatText(value?: string | null, fallback = "-") {
  return value && value.trim() ? value : fallback;
}

export function buildInitials(value: string) {
  return value
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part.charAt(0).toUpperCase())
    .join("");
}

export function getPaginationWindow({
  page,
  totalPages,
  windowSize,
}: {
  page: number;
  totalPages: number;
  windowSize: number;
}) {
  const start = Math.max(1, page - windowSize);
  const end = Math.min(totalPages, page + windowSize);
  const values: number[] = [];

  for (let index = start; index <= end; index += 1) {
    values.push(index);
  }

  return values;
}

export const SECURITY_SCORE_STORAGE_KEY = "vulncontext.securityScore";
const LEGACY_SECURITY_SCORE_STORAGE_KEY = ["vulncontext", ["control", "Question", "naire"].join("")].join(".");

export const DEFAULT_CONTROL_CONTEXT: Record<string, number> = {
  prevent_patch_maturity: 4,
  prevent_mfa_maturity: 5,
  prevent_segmentation_maturity: 3,
  prevent_hardening_maturity: 4,
  detect_logging_maturity: 3,
  detect_siem_maturity: 4,
  detect_speed_maturity: 3,
  respond_plan_maturity: 4,
  respond_speed_maturity: 3,
  respond_automation_maturity: 2,
  contain_edr_maturity: 4,
  contain_privilege_maturity: 3,
  contain_data_maturity: 5,
};

export type NestedControlContext = {
  prevent: {
    patch_maturity: number;
    mfa_maturity: number;
    segmentation_maturity: number;
    hardening_maturity: number;
  };
  detect: {
    logging_maturity: number;
    siem_maturity: number;
    speed_maturity: number;
  };
  respond: {
    plan_maturity: number;
    speed_maturity: number;
    automation_maturity: number;
  };
  contain: {
    edr_maturity: number;
    privilege_maturity: number;
    data_maturity: number;
  };
};

export function toNestedControlContext(
  context: Record<string, number>
): NestedControlContext {
  return {
    prevent: {
      patch_maturity: context.prevent_patch_maturity,
      mfa_maturity: context.prevent_mfa_maturity,
      segmentation_maturity: context.prevent_segmentation_maturity,
      hardening_maturity: context.prevent_hardening_maturity,
    },
    detect: {
      logging_maturity: context.detect_logging_maturity,
      siem_maturity: context.detect_siem_maturity,
      speed_maturity: context.detect_speed_maturity,
    },
    respond: {
      plan_maturity: context.respond_plan_maturity,
      speed_maturity: context.respond_speed_maturity,
      automation_maturity: context.respond_automation_maturity,
    },
    contain: {
      edr_maturity: context.contain_edr_maturity,
      privilege_maturity: context.contain_privilege_maturity,
      data_maturity: context.contain_data_maturity,
    },
  };
}

export function fromNestedControlContext(
  context: Record<string, Record<string, number>>
): Record<string, number> {
  return {
    prevent_patch_maturity:
      context.prevent?.patch_maturity ?? DEFAULT_CONTROL_CONTEXT.prevent_patch_maturity,
    prevent_mfa_maturity:
      context.prevent?.mfa_maturity ?? DEFAULT_CONTROL_CONTEXT.prevent_mfa_maturity,
    prevent_segmentation_maturity:
      context.prevent?.segmentation_maturity
      ?? DEFAULT_CONTROL_CONTEXT.prevent_segmentation_maturity,
    prevent_hardening_maturity:
      context.prevent?.hardening_maturity ?? DEFAULT_CONTROL_CONTEXT.prevent_hardening_maturity,
    detect_logging_maturity:
      context.detect?.logging_maturity ?? DEFAULT_CONTROL_CONTEXT.detect_logging_maturity,
    detect_siem_maturity:
      context.detect?.siem_maturity ?? DEFAULT_CONTROL_CONTEXT.detect_siem_maturity,
    detect_speed_maturity:
      context.detect?.speed_maturity ?? DEFAULT_CONTROL_CONTEXT.detect_speed_maturity,
    respond_plan_maturity:
      context.respond?.plan_maturity ?? DEFAULT_CONTROL_CONTEXT.respond_plan_maturity,
    respond_speed_maturity:
      context.respond?.speed_maturity ?? DEFAULT_CONTROL_CONTEXT.respond_speed_maturity,
    respond_automation_maturity:
      context.respond?.automation_maturity
      ?? DEFAULT_CONTROL_CONTEXT.respond_automation_maturity,
    contain_edr_maturity:
      context.contain?.edr_maturity ?? DEFAULT_CONTROL_CONTEXT.contain_edr_maturity,
    contain_privilege_maturity:
      context.contain?.privilege_maturity ?? DEFAULT_CONTROL_CONTEXT.contain_privilege_maturity,
    contain_data_maturity:
      context.contain?.data_maturity ?? DEFAULT_CONTROL_CONTEXT.contain_data_maturity,
  };
}

export function readControlContext(): Record<string, number> {
  if (typeof window === "undefined") {
    return DEFAULT_CONTROL_CONTEXT;
  }

  try {
    const raw =
      window.localStorage.getItem(SECURITY_SCORE_STORAGE_KEY)
      ?? window.localStorage.getItem(LEGACY_SECURITY_SCORE_STORAGE_KEY);
    if (!raw) {
      return DEFAULT_CONTROL_CONTEXT;
    }

    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") {
      return DEFAULT_CONTROL_CONTEXT;
    }

    return Object.fromEntries(
      Object.entries(DEFAULT_CONTROL_CONTEXT).map(([key, fallback]) => {
        const value = Number((parsed as Record<string, unknown>)[key]);
        return [key, Number.isFinite(value) ? value : fallback];
      })
    );
  } catch {
    return DEFAULT_CONTROL_CONTEXT;
  }
}

export function writeControlContext(context: Record<string, number>) {
  if (typeof window === "undefined") {
    return;
  }

  window.localStorage.setItem(
    SECURITY_SCORE_STORAGE_KEY,
    JSON.stringify(context)
  );
}

import type { SortOrder } from "../../types";

export interface SortState<TSortKey extends string> {
  key: TSortKey;
  order: SortOrder;
}

export function toggleSort<TSortKey extends string>(
  currentSort: SortState<TSortKey>,
  nextKey: TSortKey
): SortState<TSortKey> {
  if (currentSort.key === nextKey) {
    return {
      key: nextKey,
      order: currentSort.order === "asc" ? "desc" : "asc",
    };
  }

  return {
    key: nextKey,
    order: "asc",
  };
}

export function compareSortValues(
  left: string | number | boolean | null,
  right: string | number | boolean | null,
  order: SortOrder
) {
  const direction = order === "asc" ? 1 : -1;

  if (typeof left === "string" || typeof right === "string") {
    const normalizedLeft = String(left ?? "").toLowerCase();
    const normalizedRight = String(right ?? "").toLowerCase();
    return normalizedLeft.localeCompare(normalizedRight) * direction;
  }

  const normalizedLeft =
    typeof left === "boolean" ? Number(left) : (left ?? Number.NEGATIVE_INFINITY);
  const normalizedRight =
    typeof right === "boolean" ? Number(right) : (right ?? Number.NEGATIVE_INFINITY);
  return (normalizedLeft - normalizedRight) * direction;
}

